   [203]={next_id=204, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="押送到刑场的是我，你就算在战场上背后捅我，我也毫无怨言。", msg_color="", msg_size=0, talker="维特伯爵", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7193", 0, 0, 21.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [204]={next_id=205, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但发出号召的人不是我，是高奈莉娅殿下。", msg_color="", msg_size=0, talker="维特伯爵", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7193", 0, 0, 21.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
